@classmethod
def from_neurodata_object(cls, neurodata_object: Container, dataset_name: Literal["data", "timestamps"]) -> Self:
    dataset_io_configuration = super().from_neurodata_object(
        neurodata_object=neurodata_object, dataset_name=dataset_name
    )

    candidate_dataset = getattr(neurodata_object, dataset_name)
    if isinstance(candidate_dataset, h5py.Dataset):  # For HDF5, update the compression info from the on-disk dataset
        dataset_io_configuration.compression_method = candidate_dataset.compression
        dataset_io_configuration.compression_options = dict(compression_opts=candidate_dataset.compression_opts)

    return dataset_io_configuration
